-- Topic packs: every question belongs to a topic, so creators can fill their page
-- with questions about what they're into (Movies, Money, Hot takes, …). Adds ~120
-- questions in a more grown-up, opinion-based tone, and retires four that read as
-- too childish. Retired questions stay in quizzes that already use them.
--
-- Topic ids must match TOPICS in src/lib/quiz/topics.ts (checked by a test).

alter table public.questions add column topic text check (topic is null or topic ~ '^[a-z_]{2,20}$');
create index questions_topic_idx on public.questions (topic) where active;

update public.questions set topic = v.topic from (values
  ('chai', 'food'),
  ('crave', 'food'),
  ('comfort', 'food'),
  ('sweet', 'food'),
  ('street_food', 'food'),
  ('biryani', 'hot_takes'),
  ('spicy', 'food'),
  ('cook', 'food'),
  ('decision', 'food'),
  ('travel', 'travel'),
  ('group_trip', 'travel'),
  ('transport', 'travel'),
  ('movie', 'movies'),
  ('show', 'movies'),
  ('music', 'music'),
  ('battery', 'tech'),
  ('texts', 'tech'),
  ('viral', 'tech'),
  ('app', 'tech'),
  ('call', 'tech'),
  ('cricket', 'sport'),
  ('exam', 'nostalgia'),
  ('dream_job', 'work'),
  ('shopping', 'money'),
  ('money', 'money'),
  ('sunday', 'life'),
  ('morning', 'life'),
  ('party', 'life'),
  ('fear', 'life'),
  ('bag', 'life'),
  ('weekend_plan', 'life'),
  ('hobby', 'life'),
  ('angry', 'life'),
  ('gift', 'life'),
  ('holiday', 'life'),
  ('photo', 'life'),
  ('sleep', 'life'),
  ('rain', 'life'),
  ('friend_role', 'life'),
  ('late', 'life')
) as v(id, topic) where questions.id = v.id;

update public.questions set active = false where id in ('power', 'pet', 'season', 'dessert');

on conflict (id) do nothing;

